#!/bin/bash# =============================================================================#  backup-postgres.sh#  PostgreSQL Backup Script â€” Sistema Nacional de CÃ³mputo Electoral Bolivia##  Uses pg_dump inside the postgres-primary container.#  Output is copied to: ./postgres/backups/YYYY-MM-DD_HH-MM-SS.dump##  Usage (from module root):#    bash scripts/backup-postgres.sh##  On Windows (PowerShell / Git Bash):#    bash scripts/backup-postgres.sh# =============================================================================set -eCONTAINER="postgres-primary"DB_NAME="oep_oficial"DB_USER="oep_user"TIMESTAMP=$(date +%Y-%m-%d_%H-%M-%S)BACKUP_FILE="./postgres/backups/${TIMESTAMP}.dump"echo "================================================="echo " OEP â€” PostgreSQL Backup"echo " Container : $CONTAINER"echo " Database  : $DB_NAME"echo " Timestamp : $TIMESTAMP"echo "================================================="# Verify container is runningif ! docker inspect "$CONTAINER" > /dev/null 2>&1; then  echo "[ERROR] Container '$CONTAINER' not found. Is the cluster running?"  exit 1fi# Create backup directory if it does not existmkdir -p "./postgres/backups"# Run pg_dump inside the container (custom format for easy restore)echo "[INFO] Running pg_dump (custom format)..."docker exec "$CONTAINER" pg_dump \  -U "$DB_USER" \  -d "$DB_NAME" \  -Fc \  -f "/tmp/oep_backup_${TIMESTAMP}.dump"# Copy from container to hostecho "[INFO] Copying backup to host..."docker cp "${CONTAINER}:/tmp/oep_backup_${TIMESTAMP}.dump" "$BACKUP_FILE"# Cleanup inside containerdocker exec "$CONTAINER" rm -f "/tmp/oep_backup_${TIMESTAMP}.dump"# Show resultFILESIZE=$(du -h "$BACKUP_FILE" 2>/dev/null | cut -f1)echo ""echo "[OK] Backup complete."echo "     File    : $BACKUP_FILE"echo "     Size    : $FILESIZE"echo ""echo "     Restore with:"echo "       bash scripts/restore-postgres.sh $BACKUP_FILE"echo "================================================="